    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "The all-degree normalized homotopy", H("The all-degree normalized homotopy"), Blocks(
        Paragraph(Text("All degrees q are natural numbers. Define the endomorphism error E(q) as (phiOp q).comp(boundaryOp q)+(boundaryOp(q+1)).comp(phiOp(q+1))+idOp(q+1)-hOp(q+1), acting in degree q+1. Composition M₂.comp M₁ applies M₁ first. The base error is a diagonal degeneracy, and E(q+1) is E(q).prime. Structural norms are closed under prime, so E(q) is a norm for every q.")),
        Paragraph(Text("Let C : Type u have Category.{v} C and Abelian C, with independent u,v, and let X be arbitrary bisimplicial data in C. Moore retraction kills the realized error. Sandwich the raw degree-raising family between diagonal Moore inclusion and retraction to obtain phiHomNorm. Its component i → i+1 is inclusionN₂.f i followed by (phiOp i).realize X and retractionN₂.f(i+1); other components are zero.")),
        Paragraph(Text("The resulting Homotopy has source normalizedAlexanderWhitney X followed by normalizedShuffleMap X and target the identity of N₂(X). In Lean’s convention the source map equals dNext plus prevD plus the target map. Thus the homotopy sign is dΦ+Φd = AW-then-shuffle minus identity. No assertion of vanishing higher side composites is included.")),
        Describe.Lean(DescribeId.Create("ez-normalizedhomotopy-phi-op-isnorm-zero-d7e2bc"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/NormalizedHomotopy.phi_op_isNorm_zero"), H("phi_op_isNorm_zero"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("Base case for the exact induction: the degree-1 error term is a norm.")), Paragraph(Text("In this notation, lemma phi_op_isNorm_zero : IsNorm ((phiOp 0).comp (boundaryOp 0) + (boundaryOp 1).comp (phiOp 1) + idOp 1 - hOp 1)."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-normalizedhomotopy-phi-op-succ-eq-f097bf"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/NormalizedHomotopy.phi_op_succ_eq"), H("phi_op_succ_eq"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("The error term `Φ∂ + ∂Φ + i - h` satisfies the same `prime` recursion as `Φ`. After rewriting `∂ = F₀ - ∂'` and `Φ = -Φ' + h' D₀`, the remaining identity is a formal operator calculation using `lastFace_comp_prime`, `boundaryOp_comp_hOp`, and `boundary_comp_D0`.")), Paragraph(Text("In this notation, lemma phi_op_succ_eq (q : ℕ) : (phiOp (q + 1)).comp (boundaryOp (q + 1)) + (boundaryOp (q + 1 + 1)).comp (phiOp (q + 1 + 1)) + idOp (q + 1 + 1) - hOp (q + 1 + 1) = ((phiOp q).comp (boundaryOp q) + (boundaryOp (q + 1)).comp (phiOp (q + 1)) + idOp (q + 1) - hOp (q + 1)).prime."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-normalizedhomotopy-phi-op-isnorm-df1dc2"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/NormalizedHomotopy.phi_op_isNorm"), H("phi_op_isNorm"), StatementSource.FromAuthor(NormStatement), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("The error term `Φ∂ + ∂Φ + i - h` is a norm in every degree.")), Paragraph(Text("In this notation, lemma phi_op_isNorm (q : ℕ) : IsNorm ((phiOp q).comp (boundaryOp q) + (boundaryOp (q + 1)).comp (phiOp (q + 1)) + idOp (q + 1) - hOp (q + 1))."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-normalizedhomotopy-phi-comm-op-f3b0dc"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/NormalizedHomotopy.phi_comm_op"), H("phi_comm_op"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("Operator-level form of the EM homotopy identity, modulo norms. This is the realized statement corresponding to `Φ∂ + ∂Φ + i ≡ h`, obtained by killing the structural norm term from `phi_op_isNorm` with `retractionN₂`.")), Paragraph(Text("In this notation, lemma phi_comm_op (X : BisimplicialObject C) (q : ℕ) : (DerivedOp.realize X ((phiOp q).comp (boundaryOp q)) + DerivedOp.realize X ((boundaryOp (q + 1)).comp (phiOp (q + 1))) + DerivedOp.realize X (idOp (q + 1))) ≫ (retractionN₂ X).f (q + 1) = DerivedOp.realize X (hOp (q + 1)) ≫ (retractionN₂ X).f (q + 1)."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-normalizedhomotopy-phi-comm-retraction-626cc5"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/NormalizedHomotopy.phi_comm_retraction"), H("phi_comm_retraction"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("EM's homotopy identity `∂Φ + Φ∂ = ∇f - i`, after postcomposing with `retractionN₂`.")), Paragraph(Text("In this notation, lemma phi_comm_retraction (X : BisimplicialObject C) (n : ℕ) : (dNext n (phiHomRaw X) + prevD n (phiHomRaw X) + (𝟙 (F₂.obj X) : (F₂.obj X) ⟶ (F₂.obj X)).f n) ≫ (retractionN₂ X).f n = (alexanderWhitney X ≫ shuffleMap X).f n ≫ (retractionN₂ X).f n."))), DescribeRole.Theorem),
        new DocumentBlock.Section(H("inclusionN₂_comp_retractionN₂"), Blocks(Paragraph(Text("The normalized Moore complex `N₂` is a retract of `F₂`: `inclusionN₂ ≫ retractionN₂ = 𝟙`.")), Paragraph(Text("In this notation, @[reassoc] lemma inclusionN₂_comp_retractionN₂ (X : BisimplicialObject C) : inclusionN₂ X ≫ retractionN₂ X = 𝟙 (N₂.obj X).")))),
        Describe.Lean(DescribeId.Create("ez-normalizedhomotopy-phihomnorm-eebed2"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/NormalizedHomotopy.phiHomNorm"), H("phiHomNorm"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("`Φ` conjugated onto the normalized diagonal `N₂.obj X` (EM's homotopy on `K ×_N L`): `inclusionN₂ ≫ phiOp.realize ≫ retractionN₂`.")), Paragraph(Text("In this notation, noncomputable def phiHomNorm (X : BisimplicialObject C) (i j : ℕ) : (N₂.obj X).X i ⟶ (N₂.obj X).X j."))), DescribeRole.Definition),
        Describe.Lean(DescribeId.Create("ez-normalizedhomotopy-phihomnorm-zero-9fabab"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/NormalizedHomotopy.phiHomNorm_zero"), H("phiHomNorm_zero"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("The normalized homotopy family is zero away from degree increase by one.")), Paragraph(Text("In this notation, lemma phiHomNorm_zero (X : BisimplicialObject C) (i j : ℕ) (hij : ¬ (ComplexShape.down ℕ).Rel j i) : phiHomNorm X i j = 0."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-normalizedhomotopy-phihomnorm-eq-75f304"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/NormalizedHomotopy.phiHomNorm_eq"), H("phiHomNorm_eq"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("`phiHomNorm` is the conjugate of `phiHomRaw` by `inclusionN₂ … retractionN₂`.")), Paragraph(Text("In this notation, lemma phiHomNorm_eq (X : BisimplicialObject C) (i j : ℕ) : phiHomNorm X i j = (inclusionN₂ X).f i ≫ phiHomRaw X i j ≫ (retractionN₂ X).f j."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-normalizedhomotopy-dnext-phihomnorm-f1b4ec"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/NormalizedHomotopy.dNext_phiHomNorm"), H("dNext_phiHomNorm"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("`dNext` commutes with the `inclusionN₂ … retractionN₂` conjugation (both are chain maps).")), Paragraph(Text("In this notation, lemma dNext_phiHomNorm (X : BisimplicialObject C) (i : ℕ) : dNext i (phiHomNorm X) = (inclusionN₂ X).f i ≫ dNext i (phiHomRaw X) ≫ (retractionN₂ X).f i."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-normalizedhomotopy-prevd-phihomnorm-5db9d7"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/NormalizedHomotopy.prevD_phiHomNorm"), H("prevD_phiHomNorm"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("`prevD` commutes with the `inclusionN₂ … retractionN₂` conjugation (both are chain maps).")), Paragraph(Text("In this notation, lemma prevD_phiHomNorm (X : BisimplicialObject C) (j : ℕ) : prevD j (phiHomNorm X) = (inclusionN₂ X).f j ≫ prevD j (phiHomRaw X) ≫ (retractionN₂ X).f j."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-normalizedhomotopy-normalizedaw-shuffle-eq-6ac26c"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/NormalizedHomotopy.normalizedAW_shuffle_eq"), H("normalizedAW_shuffle_eq"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("**(6b)** The normalized `AW ≫ ∇` is the `N₂`-conjugate of the unnormalized `AW ≫ ∇`. Unfolding the definitions, `normalizedAlexanderWhitney ≫ normalizedShuffleMap` `= ι₂ ≫ AW ≫ (retractionN₁ ≫ inclusionN₁) ≫ ∇ ≫ ρ₂`; the inner Dold–Kan round-trip `retractionN₁ ≫ inclusionN₁` (the `PInfty` idempotent on `F₁`) is absorbed, leaving `ι₂ ≫ (AW ≫ ∇) ≫ ρ₂`.")), Paragraph(Text("In this notation, lemma normalizedAW_shuffle_eq (X : BisimplicialObject C) : normalizedAlexanderWhitney X ≫ normalizedShuffleMap X = inclusionN₂ X ≫ (alexanderWhitney X ≫ shuffleMap X) ≫ retractionN₂ X."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-normalizedhomotopy-homotopyawshufflenormalized-df6f51"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/NormalizedHomotopy.homotopyAWShuffleNormalized"), H("homotopyAWShuffleNormalized"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("**`AW ≫ ∇ ≃ 𝟙` on the normalized diagonal `N₂`** via the Eilenberg–Mac Lane homotopy `Φ` (EM Thm 2.1a, `∂Φ + Φ∂ = ∇f − i`). This is the contraction homotopy used by `eilenbergZilberNormalized` (`BisimplicialNormalized.lean`).")), Paragraph(Text("In this notation, noncomputable def homotopyAWShuffleNormalized (X : BisimplicialObject C) : Homotopy (normalizedAlexanderWhitney X ≫ normalizedShuffleMap X) (𝟙 (N₂.obj X))."))), DescribeRole.Definition))));
